#include "stdafx.h"#include "ControlBuilderE.h"#include <HBridge2SysParam.h>#include <Param.h>static SHParam s_params[9999];void operator << ( CParams &parm, SHParam &thr ){  //parm.SetDefaultValue(thr.pDefValue);  switch( thr.Type )  {  case 'D':    parm.Set( NULL, (LPSTR)thr.ParamName, *(double*)thr.pAddr, thr.Size );    break;  case 'I':    parm.Set( NULL, (LPSTR)thr.ParamName, *(int*)thr.pAddr, thr.Size );    break;  case 'W':    parm.Set( NULL, (LPSTR)thr.ParamName, *(BYTE*)thr.pAddr, thr.Size );    break;  default:    ASS(0);    return;  }}int KControlBuilderE::GetParams( char * StrName ){  ZeroMemory( s_params, sizeof(s_params) );  KHBridge2SysParam paramCont( s_params, _countof(s_params) );  int r = KControlBuilder::GetParams( paramCont );  for( int n=0, Count(paramCont.Count()); n<Count; ++n )  {    SHParam &src = s_params[n];    CParams & __P = CParams::Get();    __P << src;  }  return 0;}